<script setup lang="ts">
type Dtr={BatchID:number,AgencyName:string,ClientName:string,SiteName:string,PeriodStart:string,PeriodEnd:string}
type Row={EmployeeID:number,EmployeeNumber:string|null,EmployeeName:string,DeploymentType:'Regular'|'Reliever',Days:number,[key:string]:any}
type Shift={ShiftCodeID:number,ShiftCode:string,ShiftName:string,TimeIn:string,TimeOut:string,RegularHours:number}
const props=defineProps<{dtr:Dtr}>();const emit=defineEmits<{close:[],changed:[]}>()
const fields=[['RegularHours','Regular hours'],['OTHours','Regular OT'],['OTExtHours','OT extension'],['NightDiffHours','Night differential'],['RestDayHours','Rest day hours'],['RestDayOTHours','Rest day OT'],['LegalHolidayHours','Legal holiday hours'],['LegalHolidayOTHours','Legal holiday OT'],['RestDayLegalHolidayHours','Rest day legal holiday'],['RestDayLegalHolidayOTHours','Rest day legal holiday OT'],['SpecialHolidayHours','Special holiday hours'],['SpecialHolidayOTHours','Special holiday OT'],['RestDaySpecialHolidayHours','Rest day special holiday'],['RestDaySpecialHolidayOTHours','Rest day special holiday OT'],['LateHours','Late hours'],['UndertimeHours','Undertime hours'],['BreakHours','Break hours']] as const
const rows=ref<Row[]>([]),shifts=ref<Shift[]>([]),search=ref(''),applied=ref(''),picker=ref(false),employeeSearch=ref(''),employees=ref<any[]>([]),selectedType=ref<'Regular'|'Reliever'>('Regular'),selected=ref<Row|null>(null),daily=ref<any[]>([]),dailyOpen=ref(false),saving=ref(false),error=ref('')
const visibleRows=computed(()=>{const q=applied.value.toLowerCase();return !q?rows.value:rows.value.filter(r=>`${r.EmployeeID} ${r.EmployeeNumber||''} ${r.EmployeeName}`.toLowerCase().includes(q))})
function dayLabel(v:string){return new Date(`${v.slice(0,10)}T00:00:00`).toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'})}
function dates(){const result:string[]=[];for(let d=new Date(`${props.dtr.PeriodStart.slice(0,10)}T00:00:00`);d<=new Date(`${props.dtr.PeriodEnd.slice(0,10)}T00:00:00`);d.setDate(d.getDate()+1))result.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`);return result}
function blankDay(date:string){const item:any={AttendanceDate:date,ShiftCodeID:'',AttendanceStatus:'Present',TimeIn:'',TimeOut:'',Remarks:''};fields.forEach(([key])=>item[key]=0);return item}
async function load(){try{const r=await $fetch<any>(`/api/attendance/dtr/${props.dtr.BatchID}/records`);rows.value=r.records||[];shifts.value=r.shifts||[]}catch(e:any){error.value=e?.data?.statusMessage||'Unable to load DTR attendance.'}}
async function findEmployees(){try{const r=await $fetch<any>(`/api/attendance/dtr/${props.dtr.BatchID}/employees`,{query:employeeSearch.value?{search:employeeSearch.value}:undefined});employees.value=r.employees||[]}catch(e:any){error.value=e?.data?.statusMessage||'Unable to load employees.'}}
async function addEmployee(employee:any){saving.value=true;try{await $fetch(`/api/attendance/dtr/${props.dtr.BatchID}/employees`,{method:'POST',body:{EmployeeID:employee.EmployeeID,DeploymentType:selectedType.value}});picker.value=false;await load();emit('changed')}catch(e:any){error.value=e?.data?.statusMessage||'Unable to add employee.'}finally{saving.value=false}}
async function changeType(row:Row){try{await $fetch(`/api/attendance/dtr/${props.dtr.BatchID}/employees`,{method:'PUT',body:{EmployeeID:row.EmployeeID,DeploymentType:row.DeploymentType}});emit('changed')}catch(e:any){error.value=e?.data?.statusMessage||'Unable to update deployment type.';await load()}}
function openDaily(row:Row){selected.value=row;daily.value=dates().map(blankDay);dailyOpen.value=true}
function applyShift(entry:any){const shift=shifts.value.find(s=>String(s.ShiftCodeID)===String(entry.ShiftCodeID));if(!shift)return;entry.RegularHours=Number(shift.RegularHours||0);const inTime=String(shift.TimeIn).slice(0,5),outTime=String(shift.TimeOut).slice(0,5);entry.TimeIn=`${entry.AttendanceDate}T${inTime}`;const outDate=new Date(`${entry.AttendanceDate}T${outTime}`);if(outTime<=inTime)outDate.setDate(outDate.getDate()+1);entry.TimeOut=`${outDate.getFullYear()}-${String(outDate.getMonth()+1).padStart(2,'0')}-${String(outDate.getDate()).padStart(2,'0')}T${outTime}`}
async function saveDaily(){if(!selected.value)return;const entries=daily.value.filter(entry=>entry.ShiftCodeID||fields.some(([key])=>Number(entry[key])>0)||entry.AttendanceStatus!=='Present');if(!entries.length){error.value='Choose a shift code or enter hours for at least one day.';return}saving.value=true;error.value='';try{for(const entry of entries)await $fetch(`/api/attendance/dtr/${props.dtr.BatchID}/records`,{method:'POST',body:{EmployeeID:selected.value.EmployeeID,...entry}});dailyOpen.value=false;await load();emit('changed')}catch(e:any){error.value=e?.data?.statusMessage||'Unable to save daily attendance.'}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="shell"><section class="workspace"><button class="close" @click="emit('close')">x</button><header><p>ATTENDANCE RECORDS</p><h2>{{dtr.ClientName}} - {{dtr.SiteName}}</h2><span>DTR-{{String(dtr.BatchID).padStart(4,'0')}} - {{dayLabel(dtr.PeriodStart)}} to {{dayLabel(dtr.PeriodEnd)}}</span></header><div class="toolbar"><input v-model.trim="search" placeholder="Search employee ID, number, or name"><button class="secondary" @click="applied=search">Search</button><button class="primary" @click="picker=true;findEmployees()">+ Add employee</button></div><p v-if="error" class="error">{{error}}</p><div class="table-wrap"><table><thead><tr><th>Employee ID</th><th>Employee name</th><th>Type</th><th>Days</th><th v-for="field in fields" :key="field[0]">{{field[1]}}</th><th class="sticky">Actions</th></tr></thead><tbody><tr v-for="row in visibleRows" :key="row.EmployeeID"><td>EMP-{{String(row.EmployeeID).padStart(4,'0')}}<small>{{row.EmployeeNumber||'No employee no.'}}</small></td><td>{{row.EmployeeName}}</td><td><select v-model="row.DeploymentType" class="type-select" @change="changeType(row)"><option>Regular</option><option>Reliever</option></select></td><td>{{row.Days}}</td><td v-for="field in fields" :key="field[0]">{{row[field[0]]}}</td><td class="sticky action"><button class="primary" @click="openDaily(row)">Add attendance</button></td></tr><tr v-if="!rows.length"><td :colspan="5+fields.length" class="empty">No employee has been added to this DTR yet.</td></tr></tbody></table></div></section><div v-if="picker" class="layer" @click.self="picker=false"><section class="modal"><button class="close" @click="picker=false">x</button><h3>Add employee to DTR</h3><p>Only active employees under the DTR agency are shown.</p><div class="picker-tools"><input v-model.trim="employeeSearch" placeholder="Search employee ID, number, or name" @keyup.enter="findEmployees"><button class="secondary" @click="findEmployees">Search</button><select v-model="selectedType"><option>Regular</option><option>Reliever</option></select></div><div class="employee-list"><button v-for="employee in employees" :key="employee.EmployeeID" @click="addEmployee(employee)"><strong>EMP-{{String(employee.EmployeeID).padStart(4,'0')}} - {{employee.EmployeeName}}</strong><span>{{employee.EmployeeNumber||'No employee no.'}} - {{employee.PositionName}} - Add as {{selectedType}}</span></button><p v-if="!employees.length">No agency employee found.</p></div></section></div><div v-if="dailyOpen&&selected" class="layer" @click.self="dailyOpen=false"><form class="daily-modal" @submit.prevent="saveDaily"><button class="close" type="button" @click="dailyOpen=false">x</button><h3>Daily attendance by shift code</h3><p><strong>EMP-{{String(selected.EmployeeID).padStart(4,'0')}} - {{selected.EmployeeName}}</strong>. Select a shift for each day; its time and regular hours are prefilled, then adjust any hour field if needed.</p><div class="daily-list"><details v-for="entry in daily" :key="entry.AttendanceDate" open><summary>{{dayLabel(entry.AttendanceDate)}} <span>{{entry.ShiftCodeID?shifts.find(s=>String(s.ShiftCodeID)===String(entry.ShiftCodeID))?.ShiftCode:'No shift selected'}}</span></summary><div class="day-grid"><label>Shift code<select v-model="entry.ShiftCodeID" @change="applyShift(entry)"><option value="">No shift / manual</option><option v-for="shift in shifts" :key="shift.ShiftCodeID" :value="shift.ShiftCodeID">{{shift.ShiftCode}} - {{shift.ShiftName}}</option></select></label><label>Status<select v-model="entry.AttendanceStatus"><option>Present</option><option>Absent</option><option>Late</option><option>Half-Day</option><option>On-Leave</option><option>Holiday</option><option>Rest Day</option></select></label><label>Time in<input v-model="entry.TimeIn" type="datetime-local"></label><label>Time out<input v-model="entry.TimeOut" type="datetime-local"></label><label v-for="field in fields" :key="field[0]">{{field[1]}}<input v-model.number="entry[field[0]]" type="number" min="0" max="24" step="0.25"></label><label class="remarks">Remarks<textarea v-model.trim="entry.Remarks" maxlength="255"></textarea></label></div></details></div><p v-if="error" class="error">{{error}}</p><footer><button class="secondary" type="button" @click="dailyOpen=false">Cancel</button><button class="primary" :disabled="saving">{{saving?'Saving...':'Save selected days'}}</button></footer></form></div></div></template>
<style>.shell{position:fixed;z-index:60;inset:0;background:rgba(14,28,55,.55);padding:18px}.workspace{position:relative;height:100%;box-sizing:border-box;padding:28px;background:#f8faff;border-radius:16px;overflow:auto}.close{position:absolute;right:20px;top:13px;border:0;background:transparent;font-size:25px;cursor:pointer;color:#12345d}.workspace header p{margin:0 0 7px;color:#4975bd;font-size:12px;font-weight:800;letter-spacing:.08em}.workspace h2,.modal h3,.daily-modal h3{margin:0;color:#112f5c}.workspace header span,.modal>p,.daily-modal>p{display:block;margin-top:7px;color:#64738d}.toolbar,.picker-tools{display:flex;gap:10px;margin:24px 0 14px}.toolbar input,.picker-tools input{width:min(560px,100%)}.shell input,.shell select,.shell textarea{box-sizing:border-box;min-height:42px;border:1px solid #cfdaeb;border-radius:8px;background:#fff;color:#1f3b66;font:inherit;padding:0 12px}.shell textarea{min-height:70px;padding:10px}.shell .primary,.shell .secondary{border:1px solid #d4deed;border-radius:8px;padding:10px 14px;background:#fff;color:#1d4bcb;font:inherit;font-weight:700;cursor:pointer}.shell .primary{background:#2867d8;border-color:#2867d8;color:#fff}.table-wrap{overflow:auto;border:1px solid #dce5f1;border-radius:12px;background:#fff}.table-wrap table{border-collapse:separate;border-spacing:0;min-width:2280px;width:100%}.table-wrap th,.table-wrap td{padding:12px 14px;border-bottom:1px solid #e5edf7;text-align:left;white-space:nowrap}.table-wrap th{background:#f1f5fc;color:#2d4b76;font-size:12px}.table-wrap small{display:block;margin-top:4px;color:#7888a3}.type-select{min-height:34px!important;border-radius:999px!important;padding:0 10px;background:#e7edff!important;color:#2d4ac6!important;font-size:12px!important;font-weight:800}.sticky{position:sticky;right:0;z-index:2;background:#fff;box-shadow:-5px 0 9px rgba(33,57,94,.07)}th.sticky{background:#f1f5fc;z-index:3}.action{min-width:150px}.empty{text-align:center;color:#718099;padding:50px!important}.error{color:#b42318}.layer{position:fixed;z-index:70;inset:0;display:grid;place-items:center;padding:20px;background:rgba(14,28,55,.6)}.modal,.daily-modal{position:relative;box-sizing:border-box;width:min(790px,100%);max-height:90vh;overflow:auto;padding:28px;background:#fff;border-radius:15px}.employee-list{border:1px solid #dce5f1;border-radius:9px;overflow:auto;max-height:420px}.employee-list button{display:block;width:100%;border:0;border-bottom:1px solid #e4ebf5;background:#fff;padding:14px;text-align:left;cursor:pointer}.employee-list button:hover{background:#f1f5ff}.employee-list span{display:block;margin-top:5px;color:#63738d;font-size:13px}.employee-list p{padding:12px;color:#718099}.daily-modal{width:min(1080px,100%)}.daily-list{margin-top:18px}.daily-list details{margin-bottom:10px;border:1px solid #dce5f1;border-radius:9px;background:#fbfcff}.daily-list summary{padding:13px 15px;color:#183965;font-weight:800;cursor:pointer}.daily-list summary span{margin-left:10px;color:#587091;font-size:13px;font-weight:600}.day-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:0 15px 15px}.day-grid label{color:#415372;font-size:12px;font-weight:800}.day-grid input,.day-grid select,.day-grid textarea{width:100%;margin-top:5px}.remarks{grid-column:span 3}.daily-modal footer{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}@media(max-width:760px){.shell{padding:0}.workspace{border-radius:0}.toolbar,.picker-tools{flex-wrap:wrap}.day-grid{grid-template-columns:1fr}.remarks{grid-column:auto}}</style>
